from collections import OrderedDict

def cache_sim(capacity, ttl, ops):
    cache = OrderedDict()  # key -> (value, write_time)
    results = []

    def is_expired(key, t):
        if key not in cache:
            return True
        _, wt = cache[key]
        return t >= wt + ttl

    for op in ops:
        kind = op[0]
        t = op[1]
        key = op[2]
        if kind == 'put':
            value = op[3]
            if key in cache:
                if is_expired(key, t):
                    del cache[key]
                else:
                    del cache[key]
            if key not in cache and len(cache) >= capacity:
                # evict expired entries first? per spec, expired entries count as absent,
                # but eviction only mentioned for capacity full with LRU logic.
                # Need to remove any expired entries lazily before eviction check.
                # Clean up expired entries first.
                expired_keys = [k for k, (v, wt) in cache.items() if t >= wt + ttl]
                for k in expired_keys:
                    del cache[k]
            if key not in cache and len(cache) >= capacity:
                # evict least recently used
                cache.popitem(last=False)
            cache[key] = (value, t)
            cache.move_to_end(key)
        elif kind == 'get':
            if key in cache and not is_expired(key, t):
                value, wt = cache[key]
                cache.move_to_end(key)
                results.append(value)
            else:
                if key in cache:
                    del cache[key]
                results.append(-1)
    return results

